//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 0u32;

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => {
                return Err(error);
            }
            Err(_) => sleeper.sleep_ms(retry_delay(
                config.base_delay_ms,
                config.max_delay_ms,
                attempt,
            )),
        }
    }
}

fn retry_delay(base_delay_ms: u64, max_delay_ms: u64, retry_number: u32) -> u64 {
    if base_delay_ms == 0 || base_delay_ms >= max_delay_ms {
        return base_delay_ms.min(max_delay_ms);
    }

    let mut delay = base_delay_ms;
    let mut step = 1;
    // A u64 can be doubled at most 64 times before reaching any positive
    // u64 cap, so large attempt counts do not require large loops.
    while step < retry_number && step <= 64 {
        delay = delay.saturating_mul(2);
        if delay >= max_delay_ms {
            return max_delay_ms;
        }
        step += 1;
    }
    delay.min(max_delay_ms)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn retry_delay_saturates_without_overflow() {
        assert_eq!(retry_delay(u64::MAX / 2 + 1, u64::MAX, 2), u64::MAX);
        assert_eq!(retry_delay(1, 100, u32::MAX), 100);
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms: 10,
        max_delay_ms: 25,
    }
}

#[test]
fn retries_transient_errors_with_bounded_exponential_delays() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(5), &mut sleeper, || {
        calls += 1;
        if calls < 5 {
            Err(RetryError::Transient("temporary".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 5);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
}

#[test]
fn max_attempts_includes_the_first_call() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(3), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("temporary".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("temporary".into())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn permanent_errors_return_without_retrying() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(5), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn zero_attempt_budget_still_invokes_job_once() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(0), &mut sleeper, || {
        calls += 1;
        Ok(())
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}
